  ('g2-c10-l9', 'g2-c10', 'Bài 9: So sánh các số có ba chữ số', 'learn', 'So sánh hai số có ba chữ số theo từng hàng', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"245 và 254, số nào lớn hơn? Hai số này nhìn giống nhau quá! 🤔"}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"So lần lượt từng hàng","explanation":"So hàng trăm trước. Bằng nhau thì so hàng chục. Bằng nhau nữa thì so hàng đơn vị.","rule":"245 và 254: hàng trăm đều là 2, so hàng chục 4 < 5. Vậy 245 < 254.","points":["Chỉ so tiếp khi hàng trước bằng nhau.","376 > 299 vì 3 trăm > 2 trăm.","Số có nhiều chữ số hơn thì lớn hơn: 1000 > 999."]}},{"type":"visual","content":{"text":"245  <  254\n(2 = 2; 4 < 5)","comparison":{"left":245,"sign":"<","right":254},"table":{"headers":["So sánh","Vì sao"],"rows":[["245 < 254","hàng trăm đều là 2, hàng chục 4 < 5"],["376 > 369","hàng chục 7 > 6"]],"label":"So sánh số có ba chữ số: so từ hàng trăm trở xuống"}}},{"type":"quiz","content":{"question":"Trong hai số 245 và 254, số nào lớn hơn?","options":[245,254,"Hai số bằng nhau"],"answer":254,"mascotHint":"Hàng trăm bằng nhau, so hàng chục: 4 < 5 nên 245 < 254."}},{"type":"quiz","content":{"question":"Trong hai số 376 và 299, số nào lớn hơn?","options":[376,299,"Hai số bằng nhau"],"answer":376,"mascotHint":"3 trăm > 2 trăm nên 376 > 299, không cần so tiếp."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["So hàng trăm → hàng chục → hàng đơn vị.","245 < 254; 376 > 299."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c10-l10', 'g2-c10', 'Bài 10: Thứ tự các số có ba chữ số', 'learn', 'Sắp xếp các số có ba chữ số theo thứ tự', 9, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Bé giúp Rô-bốt xếp hàng các con số từ bé đến lớn nhé! 📊"}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Sắp xếp theo thứ tự","explanation":"Muốn xếp từ bé đến lớn, bé tìm số bé nhất trước rồi lần lượt các số tiếp theo. Muốn xếp từ lớn đến bé thì làm ngược lại.","rule":"Xếp 245, 254, 199 từ bé đến lớn: 199, 245, 254. Từ lớn đến bé: 254, 245, 199.","points":["So từng cặp số để tìm số bé nhất.","199 bé nhất vì 1 trăm bé hơn 2 trăm.","Số liền trước, liền sau vẫn đúng với số có ba chữ số."]}},{"type":"visual","content":{"text":"Bé đến lớn: 199 · 245 · 254\nLớn đến bé: 254 · 245 · 199","numberLine":{"from":199,"to":254,"step":1,"marks":[199,245,254],"label":"Bé đến lớn: 199 · 245 · 254 — lớn đến bé: 254 · 245 · 199"}}},{"type":"quiz","content":{"question":"Sắp xếp ba số 320, 302, 298 theo thứ tự từ bé đến lớn:","options":["298, 302, 320","320, 302, 298","302, 298, 320","298, 320, 302"],"answer":"298, 302, 320","mascotHint":"298 < 302 < 320."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Sắp xếp thì so từng cặp số với nhau.","298 < 302 < 320."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c10-l11', 'g2-c10', 'Bài 11: Luyện tập chung chủ đề 10', 'learn', 'Ôn tập các số trong phạm vi 1 000', 10, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bé đã đi hết các số đến 1 000 rồi! Tổng kết nhé 🎉"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Tổng kết chủ đề 10","explanation":"Bé đã học đơn vị, chục, trăm, nghìn; các số tròn trăm, tròn chục; số có ba chữ số và cách so sánh.","points":["10 đơn vị = 1 chục; 10 chục = 1 trăm; 10 trăm = 1 nghìn.","Số có ba chữ số gồm trăm, chục, đơn vị.","So sánh: hàng trăm → hàng chục → hàng đơn vị."]}},{"type":"visual","content":{"text":"10 đơn vị = 1 chục\n10 chục = 1 trăm\n10 trăm = 1 nghìn = 1000","table":{"headers":["Đổi","Được"],"rows":[["10 đơn vị","1 chục"],["10 chục","1 trăm"],["10 trăm","1 nghìn = 1000"]],"label":"Luyện tập chung chủ đề 10"},"placeValue":{"headers":["Trăm","Chục","Đơn vị"],"digits":[3,8,6],"label":"386 = 300 + 80 + 6"}}},{"type":"quiz","content":{"question":"Số nào lớn nhất trong các số: 909, 990, 899, 1000?","options":[909,990,899,1000],"answer":1000,"mascotHint":"1000 là số lớn nhất trong bốn số."}},{"type":"quiz","content":{"question":"Số 708 viết thành tổng nào?","options":["700 + 8","700 + 80 + 8","70 + 8","7 + 0 + 8"],"answer":"700 + 8","mascotHint":"708 gồm 7 trăm, 0 chục, 8 đơn vị → 700 + 8."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Bé đã hoàn thành chủ đề 10.","1 nghìn = 1000 = 10 trăm."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c11-l1', 'g2-c11', 'Bài 1: Đề-xi-mét (dm)', 'learn', 'Nhận biết đề-xi-mét và quan hệ với xăng-ti-mét', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Bút chì dài 15 cm, còn quyển sách dài 2 dm. Vậy 1 dm bằng bao nhiêu cm nhỉ? 📏"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Đề-xi-mét","explanation":"ĐỀ-XI-MÉT là đơn vị đo độ dài lớn hơn xăng-ti-mét. Viết tắt là dm.","rule":"1 dm = 10 cm. Quyển sách dài 2 dm nghĩa là dài 20 cm.","points":["Đổi dm sang cm: lấy số dm nhân với 10.","Đổi cm sang dm: lấy số cm chia cho 10.","dm dùng để đo những vật vừa vừa như quyển sách, gang tay."]}},{"type":"visual","content":{"text":"1 dm = 10 cm\n2 dm = 20 cm\n30 cm = 3 dm","ruler":{"lengthCm":10,"measure":{"from":0,"to":10},"label":"1 dm = 10 cm"},"table":{"headers":["Đổi","Được"],"rows":[["1 dm","10 cm"],["2 dm","20 cm"],["30 cm","3 dm"]],"label":"Đề-xi-mét"}}},{"type":"quiz","content":{"question":"1 đề-xi-mét bằng bao nhiêu xăng-ti-mét?","options":["1 cm","10 cm","100 cm","5 cm"],"answer":"10 cm","mascotHint":"1 dm = 10 cm."}},{"type":"quiz","content":{"question":"3 dm bằng bao nhiêu xăng-ti-mét?","options":["3 cm","13 cm","30 cm","300 cm"],"answer":"30 cm","mascotHint":"3 dm = 3 × 10 = 30 cm."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["1 dm = 10 cm.","Đổi dm sang cm thì nhân với 10."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c11-l2', 'g2-c11', 'Bài 2: Mét (m)', 'learn', 'Nhận biết mét và quan hệ với đề-xi-mét, xăng-ti-mét', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Chiều cao của Rô-bốt là 1 m. Bé cao bao nhiêu mét nhỉ? 📐"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Mét","explanation":"MÉT là đơn vị đo độ dài lớn hơn đề-xi-mét. Viết tắt là m.","rule":"1 m = 10 dm = 100 cm. Chiều cao của bé khoảng 1 m đến 1 m 30 cm.","points":["1 m = 100 cm, nên 2 m = 200 cm.","Mét dùng để đo chiều cao, chiều dài phòng học, chiều dài sân.","100 cm = 10 dm = 1 m."]}},{"type":"visual","content":{"text":"1 m = 10 dm\n1 m = 100 cm","ruler":{"lengthCm":30,"measure":{"from":0,"to":30},"label":"1 m = 100 cm = 10 dm"}}},{"type":"quiz","content":{"question":"1 mét bằng bao nhiêu xăng-ti-mét?","options":["10 cm","100 cm","1000 cm","20 cm"],"answer":"100 cm","mascotHint":"1 m = 100 cm."}},{"type":"quiz","content":{"question":"1 mét bằng bao nhiêu đề-xi-mét?","options":["1 dm","10 dm","100 dm","1000 dm"],"answer":"10 dm","mascotHint":"1 m = 10 dm."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["1 m = 10 dm = 100 cm.","Mét dùng để đo chiều cao, chiều dài phòng học."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c11-l3', 'g2-c11', 'Bài 3: Ki-lô-mét (km)', 'learn', 'Nhận biết ki-lô-mét dùng để đo quãng đường dài', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Từ nhà bé đến trường dài 2 km. Vậy 1 km bằng bao nhiêu mét nhỉ? 🚌"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Ki-lô-mét","explanation":"KI-LÔ-MÉT là đơn vị đo độ dài lớn nhất bé đã học. Viết tắt là km.","rule":"1 km = 1000 m. Quãng đường dài 2 km nghĩa là dài 2000 m.","points":["km dùng để đo quãng đường giữa các địa điểm.","1 km = 1000 m, nên 3 km = 3000 m.","1000 m = 1 km."]}},{"type":"visual","content":{"text":"1 km = 1000 m\n2 km = 2000 m","table":{"headers":["Đổi","Được"],"rows":[["1 km","1000 m"],["2 km","2000 m"]],"label":"Ki-lô-mét — quãng đường dài 2 km nghĩa là 2000 m"}}},{"type":"quiz","content":{"question":"1 ki-lô-mét bằng bao nhiêu mét?","options":["10 m","100 m","1000 m","10 000 m"],"answer":"1000 m","mascotHint":"1 km = 1000 m."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["1 km = 1000 m.","km dùng để đo quãng đường dài."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c11-l4', 'g2-c11', 'Bài 4: Giới thiệu tiền Việt Nam', 'learn', 'Nhận biết các tờ tiền Việt Nam và mệnh giá', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Mẹ cho Rô-bốt một tờ tiền để đi mua bánh. Bé xem đó là tờ bao nhiêu nhé! 💵"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Tiền Việt Nam","explanation":"Tiền Việt Nam gồm nhiều tờ với mệnh giá khác nhau. Mệnh giá là số tiền ghi trên tờ tiền.","rule":"Các tờ tiền thường gặp: 100 đồng, 200 đồng, 500 đồng, 1000 đồng, 2000 đồng, 5000 đồng.","points":["Đơn vị tiền của Việt Nam là ĐỒNG.","Tờ 1000 đồng có giá trị bằng hai tờ 500 đồng.","Hai tờ 2000 đồng có giá trị bằng một tờ 5000 đồng? Không — phải thêm 1000 đồng nữa."]}},{"type":"visual","content":{"text":"100 · 200 · 500 · 1000 · 2000 · 5000 (đồng)","money":{"notes":[1000,2000,5000],"label":"Các tờ tiền Việt Nam bé thường gặp"},"table":{"headers":["Tờ tiền","Mệnh giá"],"rows":[["100 đồng","100"],["500 đồng","500"],["1000 đồng","1000"],["5000 đồng","5000"]],"label":"Giới thiệu tiền Việt Nam"}}},{"type":"quiz","content":{"question":"Đơn vị tiền tệ của Việt Nam là gì?","options":["Đồng","Đô la","Yên","Euro"],"answer":"Đồng","mascotHint":"Tiền Việt Nam tính bằng đồng."}},{"type":"quiz","content":{"question":"Một tờ 1000 đồng có giá trị bằng mấy tờ 500 đồng?","options":["1 tờ","2 tờ","5 tờ","10 tờ"],"answer":"2 tờ","mascotHint":"500 + 500 = 1000, nên cần 2 tờ 500 đồng."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Đơn vị tiền Việt Nam là đồng.","Các tờ thường gặp: 100, 200, 500, 1000, 2000, 5000 đồng."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c11-l5', 'g2-c11', 'Bài 5: Đổi tiền và tính tiền', 'learn', 'Đổi các tờ tiền và tính tiền mua hàng', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Rô-bốt có 2000 đồng, mua bánh hết 1500 đồng. Còn lại bao nhiêu nhỉ? 🍪"}},{"type":"concept","content":{"badge":"Thực Hành","title":"Cộng và trừ tiền","explanation":"Muốn biết có tất cả bao nhiêu tiền, ta CỘNG các tờ lại. Muốn biết còn lại bao nhiêu, ta TRỪ đi số đã tiêu.","rule":"1000 đồng + 500 đồng = 1500 đồng. 2000 đồng − 1500 đồng = 500 đồng.","points":["Cộng tiền khi gom các tờ lại.","Trừ tiền khi mua hàng để biết tiền thừa.","Nhớ ghi đơn vị ''đồng'' vào kết quả."]}},{"type":"visual","content":{"text":"Mua bánh: 1500 đồng\nTrả: 2000 đồng\nTiền thừa: 2000 − 1500 = 500 (đồng)","operation":{"left":2000,"sign":"−","right":1500,"result":500},"money":{"notes":[2000,1000,500],"label":"Mua bánh 1500 đồng, trả 2000 đồng, tiền thừa 500 đồng"}}},{"type":"quiz","content":{"question":"Rô-bốt có 2000 đồng, mua bánh hết 1500 đồng. Hỏi còn lại bao nhiêu tiền?","options":["300 đồng","500 đồng","1000 đồng","3500 đồng"],"answer":"500 đồng","mascotHint":"2000 − 1500 = 500 đồng."}},{"type":"quiz","content":{"question":"Bé có một tờ 2000 đồng và một tờ 1000 đồng. Bé có tất cả bao nhiêu tiền?","options":["1000 đồng","2000 đồng","3000 đồng","2100 đồng"],"answer":"3000 đồng","mascotHint":"2000 + 1000 = 3000 đồng."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Gom tiền thì cộng; mua hàng thì trừ.","2000 − 1500 = 500 đồng."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c11-l6', 'g2-c11', 'Bài 6: Thực hành và trải nghiệm đo độ dài', 'learn', 'Ước lượng và đo độ dài bằng dm, m, km', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Bé hãy ước lượng chiều dài bàn học rồi đo lại xem đoán có đúng không nhé! 📏"}},{"type":"concept","content":{"badge":"Thực Hành","title":"Chọn đơn vị đo phù hợp","explanation":"Chọn đơn vị đo cho phù hợp với vật: vật nhỏ dùng cm, vật vừa dùng dm, phòng học dùng m, quãng đường dùng km.","rule":"Bút chì dài 15 cm. Bàn học dài 12 dm. Phòng học dài 8 m. Nhà đến trường 2 km.","points":["Ước lượng trước, đo sau để kiểm tra.","Chọn sai đơn vị thì số đo vô nghĩa: không ai nói bút chì dài 15 m.","1 m = 10 dm = 100 cm; 1 km = 1000 m."]}},{"type":"visual","content":{"text":"cm → vật nhỏ\ndm → vật vừa\nm  → phòng học, sân\nkm → quãng đường","ruler":{"lengthCm":15,"measure":{"from":0,"to":15},"label":"Bút chì dài 15 cm"},"table":{"headers":["Đơn vị","Đo vật"],"rows":[["cm","vật nhỏ: bút chì"],["dm","vật vừa: bàn học"],["m","phòng học, sân"],["km","quãng đường"]],"label":"Chọn đơn vị đo cho phù hợp"}}},{"type":"quiz","content":{"question":"Đo chiều dài phòng học thì nên dùng đơn vị nào?","options":["Mét (m)","Xăng-ti-mét (cm)","Mi-li-mét (mm)","Ki-lô-mét (km)"],"answer":"Mét (m)","mascotHint":"Phòng học dài vài mét nên dùng mét."}},{"type":"quiz","content":{"question":"Quãng đường từ nhà đến trường nên đo bằng đơn vị nào?","options":["Ki-lô-mét (km)","Đề-xi-mét (dm)","Xăng-ti-mét (cm)","Mét (m)"],"answer":"Ki-lô-mét (km)","mascotHint":"Quãng đường dài nên dùng ki-lô-mét."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Chọn đơn vị đo phù hợp với vật.","cm, dm, m, km — đơn vị càng về sau càng lớn."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c11-l7', 'g2-c11', 'Bài 7: Luyện tập chung chủ đề 11', 'learn', 'Ôn tập đơn vị đo độ dài và tiền Việt Nam', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bé đã biết đo độ dài và biết dùng tiền rồi! Tổng kết nhé 🎉"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Tổng kết chủ đề 11","explanation":"Bé đã học đề-xi-mét, mét, ki-lô-mét và tiền Việt Nam.","points":["1 dm = 10 cm; 1 m = 10 dm = 100 cm; 1 km = 1000 m.","Đơn vị tiền Việt Nam là đồng.","Mua hàng thì trừ, gom tiền thì cộng."]}},{"type":"visual","content":{"text":"1 m = 100 cm\n1 km = 1000 m\n2000 đồng − 1500 đồng = 500 đồng","table":{"headers":["Đổi","Được"],"rows":[["1 m","100 cm"],["1 km","1000 m"],["2000 đồng − 1500 đồng","500 đồng"]],"label":"Luyện tập chung chủ đề 11"},"money":{"notes":[1000,500],"label":"1000 đồng + 500 đồng = 1500 đồng"}}},{"type":"quiz","content":{"question":"5 m bằng bao nhiêu xăng-ti-mét?","options":["50 cm","500 cm","5000 cm","15 cm"],"answer":"500 cm","mascotHint":"5 m = 5 × 100 = 500 cm."}},{"type":"quiz","content":{"question":"Bé mua vở hết 3000 đồng và bút hết 2000 đồng. Bé phải trả tất cả bao nhiêu?","options":["1000 đồng","5000 đồng","6000 đồng","500 đồng"],"answer":"5000 đồng","mascotHint":"3000 + 2000 = 5000 đồng."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["1 m = 100 cm; 1 km = 1000 m.","Bé đã hoàn thành chủ đề 11."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c12-l1', 'g2-c12', 'Bài 1: Phép cộng (không nhớ) trong phạm vi 1 000', 'learn', 'Đặt tính và cộng không nhớ các số có ba chữ số', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bây giờ các số đã có ba chữ số. Bé vẫn đặt tính thẳng cột như trước nhé! 🔢"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Cộng không nhớ","explanation":"Cộng lần lượt từ hàng đơn vị, đến hàng chục, rồi hàng trăm. Nếu từng hàng đều bé hơn 10 thì gọi là cộng KHÔNG NHỚ.","rule":"235 + 412: 5 + 2 = 7, 3 + 1 = 4, 2 + 4 = 6. Kết quả 647.","points":["Luôn tính từ phải sang trái.","Đặt các chữ số cùng hàng thẳng cột với nhau.","Không nhớ nghĩa là từng hàng cộng lại đều bé hơn 10."]}},{"type":"visual","content":{"text":"  235\n+ 412\n  647","operation":{"left":235,"sign":"+","right":412,"result":647},"placeValue":{"headers":["Trăm","Chục","Đơn vị"],"digits":[2,3,5],"label":"235 + 412: cộng từng hàng một, không nhớ"}}},{"type":"quiz","content":{"question":"235 + 412 bằng bao nhiêu?","options":[547,647,657,6470],"answer":647,"mascotHint":"5+2=7, 3+1=4, 2+4=6. Kết quả 647."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Cộng từ hàng đơn vị sang hàng trăm.","235 + 412 = 647."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c12-l2', 'g2-c12', 'Bài 2: Phép cộng (có nhớ) trong phạm vi 1 000', 'learn', 'Cộng có nhớ khi một hàng vượt quá 9', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"256 + 173: hàng chục 5 + 7 = 12, vượt qua 10 rồi. Bé xử lý thế nào? 🤔"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Cộng có nhớ","explanation":"Khi một hàng cộng lại được từ 10 trở lên, ta viết chữ số hàng đơn vị của kết quả và NHỚ 1 sang hàng liền trước.","rule":"256 + 173: 6 + 3 = 9, viết 9. 5 + 7 = 12, viết 2 nhớ 1. 2 + 1 + 1 = 4. Kết quả 429.","points":["Nhớ 1 sang hàng bên trái.","Có thể nhớ ở hàng chục hoặc ở hàng trăm.","356 + 127 = 483 (6+7=13 viết 3 nhớ 1; 5+2+1=8; 3+1=4)."]}},{"type":"visual","content":{"text":"  256\n+ 173\n  429\n5 + 7 = 12 → viết 2 nhớ 1","operation":{"left":256,"sign":"+","right":173,"result":429},"placeValue":{"headers":["Trăm","Chục","Đơn vị"],"digits":[2,5,6],"label":"256 + 173: 5 + 7 = 12, viết 2 nhớ 1"}}},{"type":"quiz","content":{"question":"256 + 173 bằng bao nhiêu?","options":[329,419,429,439],"answer":429,"mascotHint":"6+3=9; 5+7=12 viết 2 nhớ 1; 2+1+1=4. Kết quả 429."}},{"type":"quiz","content":{"question":"356 + 127 bằng bao nhiêu?","options":[473,483,493,423],"answer":483,"mascotHint":"6+7=13 viết 3 nhớ 1; 5+2+1=8; 3+1=4. Kết quả 483."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Cộng có nhớ: nhớ 1 sang hàng bên trái.","256 + 173 = 429."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c12-l3', 'g2-c12', 'Bài 3: Luyện tập phép cộng trong phạm vi 1 000', 'learn', 'Luyện tập cộng có nhớ và giải bài toán', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Thư viện có 265 quyển sách, nhập thêm 148 quyển. Có tất cả bao nhiêu nhỉ? 📚"}},{"type":"concept","content":{"badge":"Luyện Tập","title":"Cộng trong bài toán","explanation":"Bài toán ''có ... thêm ...'' thì dùng phép cộng. Chú ý nhớ 1 khi cần.","rule":"265 + 148: 5 + 8 = 13 viết 3 nhớ 1; 6 + 4 + 1 = 11 viết 1 nhớ 1; 2 + 1 + 1 = 4. Kết quả 413.","points":["265 + 148 = 413 (quyển sách).","Có thể phải nhớ hai lần liên tiếp.","Thử lại bằng phép trừ: 413 − 148 = 265."]}},{"type":"visual","content":{"text":"  265\n+ 148\n  413","operation":{"left":265,"sign":"+","right":148,"result":413}}},{"type":"quiz","content":{"question":"Thư viện có 265 quyển sách, nhập thêm 148 quyển. Hỏi có tất cả bao nhiêu quyển sách?","options":[313,402,413,423],"answer":413,"mascotHint":"265 + 148 = 413 quyển sách."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Cộng có thể phải nhớ nhiều lần.","265 + 148 = 413."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c12-l4', 'g2-c12', 'Bài 4: Phép trừ (không nhớ) trong phạm vi 1 000', 'learn', 'Đặt tính và trừ không mượn các số có ba chữ số', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"645 − 213 thì không phải mượn lần nào cả. Bé tính thử nhé! ✏️"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Trừ không mượn","explanation":"Trừ lần lượt từ hàng đơn vị, đến hàng chục, rồi hàng trăm. Nếu từng hàng đều trừ được thì gọi là trừ KHÔNG MƯỢN.","rule":"645 − 213: 5 − 3 = 2, 4 − 1 = 3, 6 − 2 = 4. Kết quả 432.","points":["Đặt số trừ ngay dưới số bị trừ, thẳng cột.","Trừ từ phải sang trái.","Thử lại: 432 + 213 = 645."]}},{"type":"visual","content":{"text":"  645\n− 213\n  432","operation":{"left":645,"sign":"−","right":213,"result":432}}},{"type":"quiz","content":{"question":"645 − 213 bằng bao nhiêu?","options":[422,432,442,532],"answer":432,"mascotHint":"5−3=2, 4−1=3, 6−2=4. Kết quả 432."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Trừ không mượn: trừ thẳng từng hàng.","645 − 213 = 432."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c12-l5', 'g2-c12', 'Bài 5: Phép trừ (có nhớ) trong phạm vi 1 000', 'learn', 'Trừ có mượn khi chữ số không đủ để trừ', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"534 − 268: 4 không trừ được 8. Bé phải mượn, và có thể mượn hai lần đấy! 🤔"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Trừ có mượn","explanation":"Khi chữ số của số bị trừ bé hơn chữ số cùng hàng của số trừ, ta MƯỢN 1 từ hàng bên trái.","rule":"534 − 268: 4 không trừ được 8, mượn 1 chục: 14 − 8 = 6. Hàng chục: 3 bớt 1 còn 2, 2 không trừ được 6, mượn 1 trăm: 12 − 6 = 6. Hàng trăm: 5 bớt 1 còn 4, 4 − 2 = 2. Kết quả 266.","points":["Mượn 1 ở hàng bên trái, hàng đó giảm đi 1.","Có thể phải mượn hai lần liên tiếp.","Thử lại: 266 + 268 = 534."]}},{"type":"visual","content":{"text":"  534\n− 268\n  266\n14 − 8 = 6;  12 − 6 = 6;  4 − 2 = 2","operation":{"left":534,"sign":"−","right":268,"result":266},"placeValue":{"headers":["Trăm","Chục","Đơn vị"],"digits":[5,3,4],"label":"534 − 268: mượn 1 chục rồi mượn 1 trăm"}}},{"type":"quiz","content":{"question":"534 − 268 bằng bao nhiêu?","options":[256,266,276,334],"answer":266,"mascotHint":"Mượn hai lần: 14−8=6; 12−6=6; 4−2=2. Kết quả 266."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Trừ có mượn: mượn 1 ở hàng bên trái.","534 − 268 = 266."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c12-l6', 'g2-c12', 'Bài 6: Luyện tập phép trừ trong phạm vi 1 000', 'learn', 'Luyện tập trừ có mượn và giải bài toán', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Cửa hàng có 420 kg gạo, đã bán 165 kg. Còn lại bao nhiêu ki-lô-gam? 🍚"}},{"type":"concept","content":{"badge":"Luyện Tập","title":"Trừ trong bài toán","explanation":"Bài toán ''bán đi, cho đi, bớt đi'' thì dùng phép trừ.","rule":"420 − 165: 0 không trừ được 5, mượn 1 chục: 10 − 5 = 5. Hàng chục: 2 bớt 1 còn 1, 1 không trừ được 6, mượn 1 trăm: 11 − 6 = 5. Hàng trăm: 4 bớt 1 còn 3, 3 − 1 = 2. Kết quả 255.","points":["420 − 165 = 255 (kg gạo).","Chú ý chữ số 0 ở hàng đơn vị — vẫn phải mượn bình thường.","Thử lại: 255 + 165 = 420."]}},{"type":"visual","content":{"text":"  420\n− 165\n  255","operation":{"left":420,"sign":"−","right":165,"result":255}}},{"type":"quiz","content":{"question":"Cửa hàng có 420 kg gạo, đã bán 165 kg. Hỏi còn lại bao nhiêu ki-lô-gam gạo?","options":[255,265,355,585],"answer":255,"mascotHint":"420 − 165 = 255 kg gạo."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Trừ có mượn hai lần vẫn làm như thường.","420 − 165 = 255."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c12-l7', 'g2-c12', 'Bài 7: Tìm thành phần chưa biết', 'learn', 'Tìm số hạng, số bị trừ, số trừ chưa biết', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Có một số bị che mất: ... + 145 = 320. Bé tìm giúp Rô-bốt nhé! 🔍"}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Tìm thành phần chưa biết","explanation":"Muốn tìm số hạng chưa biết, lấy tổng trừ số hạng đã biết. Muốn tìm số bị trừ, lấy hiệu cộng số trừ. Muốn tìm số trừ, lấy số bị trừ trừ hiệu.","rule":"... + 145 = 320 → số cần tìm = 320 − 145 = 175.","points":["Tìm số hạng: tổng − số hạng đã biết.","Tìm số bị trừ: hiệu + số trừ.","Tìm số trừ: số bị trừ − hiệu."]}},{"type":"visual","content":{"text":"? + 145 = 320  →  ? = 320 − 145 = 175","operation":{"left":175,"sign":"+","right":145,"result":320},"numberLine":{"from":145,"to":320,"step":5,"marks":[145,175,320],"hops":[{"from":145,"to":320,"label":"+175"}],"label":"? + 145 = 320 ⇒ ? = 320 − 145 = 175"}}},{"type":"quiz","content":{"question":"Điền số còn thiếu: ? + 145 = 320","options":[165,175,185,465],"answer":175,"mascotHint":"Số hạng chưa biết = tổng − số hạng đã biết = 320 − 145 = 175."}},{"type":"quiz","content":{"question":"Điền số còn thiếu: 500 − ? = 260","options":[240,250,260,760],"answer":240,"mascotHint":"Số trừ = số bị trừ − hiệu = 500 − 260 = 240."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Tìm số hạng: lấy tổng trừ số hạng đã biết.","Tìm số trừ: lấy số bị trừ trừ hiệu."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c12-l8', 'g2-c12', 'Bài 8: Bài toán có lời văn trong phạm vi 1 000', 'learn', 'Giải bài toán có lời văn với số có ba chữ số', 7, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Đội Một trồng 245 cây, đội Hai trồng 168 cây. Cả hai đội trồng bao nhiêu cây? 🌳"}},{"type":"concept","content":{"badge":"Giải Toán","title":"Đọc kĩ đề để chọn phép tính","explanation":"''Cả hai đội'' là gom lại thì dùng phép CỘNG. ''Đội Một hơn đội Hai bao nhiêu'' là so sánh thì dùng phép TRỪ.","rule":"Cả hai đội trồng: 245 + 168 = 413 (cây). Đội Một hơn đội Hai: 245 − 168 = 77 (cây).","points":["245 + 168: 5+8=13 viết 3 nhớ 1; 4+6+1=11 viết 1 nhớ 1; 2+1+1=4. Kết quả 413.","Đơn vị của đáp án là cây.","Luôn ghi đáp số."]}},{"type":"visual","content":{"text":"Đội Một: 245 cây\nĐội Hai: 168 cây\nCả hai đội: 245 + 168 = 413 (cây)","operation":{"left":245,"sign":"+","right":168,"result":413},"barModel":{"rows":[{"label":"Đội Một","parts":245},{"label":"Đội Hai","parts":168}],"braceLabel":"Cả hai đội: 245 + 168 = 413 cây"}}},{"type":"quiz","content":{"question":"Đội Một trồng 245 cây, đội Hai trồng 168 cây. Hỏi cả hai đội trồng được bao nhiêu cây?","options":[313,403,413,77],"answer":413,"mascotHint":"245 + 168 = 413 cây."}},{"type":"quiz","content":{"question":"Với hai đội trên, đội Một trồng nhiều hơn đội Hai bao nhiêu cây?","options":[77,87,123,413],"answer":77,"mascotHint":"245 − 168 = 77 cây."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Gom lại thì cộng; so sánh hơn kém thì trừ.","245 + 168 = 413; 245 − 168 = 77."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c12-l9', 'g2-c12', 'Bài 9: Luyện tập chung chủ đề 12', 'learn', 'Ôn tập cộng trừ trong phạm vi 1 000', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bé đã tính được với số có ba chữ số rồi! Tổng kết nhé 🎉"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Tổng kết chủ đề 12","explanation":"Bé đã học cộng trừ không nhớ và có nhớ trong phạm vi 1 000.","points":["Cộng: nhớ 1 sang hàng bên trái khi hàng đó vượt 9.","Trừ: mượn 1 từ hàng bên trái khi không đủ để trừ.","Thử lại bằng phép tính ngược để chắc chắn."]}},{"type":"visual","content":{"text":"256 + 173 = 429\n429 − 173 = 256\n534 − 268 = 266","operation":{"left":534,"sign":"−","right":268,"result":266},"table":{"headers":["Phép tính","Kết quả"],"rows":[["256 + 173","429"],["429 − 173","256"],["534 − 268","266"]],"label":"Luyện tập chung chủ đề 12"}}},{"type":"quiz","content":{"question":"372 + 259 bằng bao nhiêu?","options":[521,621,631,531],"answer":631,"mascotHint":"2+9=11 viết 1 nhớ 1; 7+5+1=13 viết 3 nhớ 1; 3+2+1=6. Kết quả 631."}},{"type":"quiz","content":{"question":"700 − 285 bằng bao nhiêu?","options":[415,425,515,985],"answer":415,"mascotHint":"10−5=5; mượn tiếp: 9−8=1; 6−2=4. Kết quả 415."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Cộng có nhớ thì nhớ 1; trừ có mượn thì mượn 1.","Bé đã hoàn thành chủ đề 12."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c13-l1', 'g2-c13', 'Bài 1: Thu thập và phân loại số liệu', 'learn', 'Biết cách thu thập số liệu và phân loại theo tiêu chí', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Cả lớp có bao nhiêu bạn thích màu đỏ, bao nhiêu bạn thích màu xanh? Làm sao biết nhỉ? 📊"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Thu thập và phân loại","explanation":"THU THẬP số liệu là hỏi và ghi lại thông tin. PHÂN LOẠI là xếp các thông tin đó vào từng nhóm theo một tiêu chí.","rule":"Hỏi từng bạn thích màu gì rồi xếp vào hai nhóm: nhóm màu đỏ và nhóm màu xanh.","points":["Tiêu chí phân loại phải rõ ràng: theo màu, theo loại quả, theo giới tính.","Mỗi thông tin chỉ thuộc một nhóm.","Thu thập xong thì mới đếm được."]}},{"type":"visual","content":{"text":"Nhóm 1: thích màu đỏ\nNhóm 2: thích màu xanh\nMỗi bạn chỉ ở một nhóm","table":{"headers":["Nhóm","Số bạn"],"rows":[["Thích màu đỏ","?"],["Thích màu xanh","?"]],"label":"Hỏi từng bạn rồi xếp vào hai nhóm — mỗi bạn chỉ ở một nhóm"}}},{"type":"quiz","content":{"question":"Phân loại các loại quả theo tiêu chí nào là hợp lí?","options":["Quả có màu đỏ và quả có màu vàng","Quả to và quả ngon","Quả và bàn ghế","Quả và bạn bè"],"answer":"Quả có màu đỏ và quả có màu vàng","mascotHint":"Tiêu chí phải rõ và mọi quả phải thuộc đúng một nhóm."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Thu thập số liệu là hỏi và ghi lại thông tin.","Phân loại là xếp thông tin vào các nhóm theo tiêu chí."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c13-l2', 'g2-c13', 'Bài 2: Kiểm đếm số liệu', 'learn', 'Dùng vạch hoặc ô để kiểm đếm số liệu', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Rô-bốt đếm số bạn thích mỗi màu bằng cách gạch từng vạch. Bé xem nhé! ✏️"}},{"type":"concept","content":{"badge":"Thực Hành","title":"Kiểm đếm bằng vạch","explanation":"Mỗi lần gặp một thông tin, bé gạch một vạch vào đúng nhóm. Cuối cùng đếm số vạch để biết số lượng.","rule":"Cứ 5 vạch thì gạch chéo một lần cho dễ đếm: |||| = 4; ||||/ = 5.","points":["Gạch theo nhóm 5 cho dễ đếm.","Đếm xong ghi số vào cạnh nhóm.","Kiểm đếm giúp biết nhóm nào nhiều nhất, nhóm nào ít nhất."]}},{"type":"visual","content":{"text":"Màu đỏ:   ||||/ ||   → 7 bạn\nMàu xanh: ||||      → 4 bạn","table":{"headers":["Màu","Số bạn"],"rows":[["Màu đỏ",7],["Màu xanh",4]],"label":"Kiểm đếm bằng vạch: cứ 5 vạch thì gạch chéo một lần"}}},{"type":"quiz","content":{"question":"Nhóm A có 7 vạch, nhóm B có 4 vạch. Nhóm nào nhiều hơn và nhiều hơn mấy?","options":["Nhóm A, nhiều hơn 3","Nhóm B, nhiều hơn 3","Bằng nhau","Nhóm A, nhiều hơn 11"],"answer":"Nhóm A, nhiều hơn 3","mascotHint":"7 − 4 = 3, nên nhóm A nhiều hơn 3."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Mỗi thông tin gạch một vạch vào đúng nhóm.","Gạch nhóm 5 cho dễ đếm."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c13-l3', 'g2-c13', 'Bài 3: Biểu đồ tranh', 'learn', 'Nhận biết biểu đồ tranh và cách dùng hình thay số', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Thay vì ghi số, Rô-bốt vẽ hình quả táo để biểu diễn số liệu. Đó là biểu đồ tranh! 🍎"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Biểu đồ tranh","explanation":"BIỂU ĐỒ TRANH dùng các hình giống nhau để biểu diễn số liệu. Mỗi hình tượng trưng cho một số lượng nhất định.","rule":"Nếu mỗi hình quả táo là 1 bạn thì 5 hình quả táo nghĩa là 5 bạn thích táo.","points":["Bên trái biểu đồ ghi tên các nhóm.","Mỗi hình tương ứng một số lượng, phải đọc kĩ chú thích.","Hình càng nhiều thì số lượng càng lớn."]}},{"type":"visual","content":{"text":"Táo:   🍎🍎🍎🍎🍎\nCam:   🍊🍊🍊\n(1 hình = 1 bạn thích)","barChart":{"title":"Bạn thích loại quả nào","items":[{"label":"Táo","value":5},{"label":"Cam","value":3}],"unit":"bạn","highlight":0}}},{"type":"quiz","content":{"question":"Trên biểu đồ tranh có 4 hình quả cam, mỗi hình là 1 bạn. Hỏi có bao nhiêu bạn thích cam?","options":[3,4,5,40],"answer":4,"items":[{"emoji":"🍊","count":4}],"mascotHint":"4 hình tương ứng 4 bạn."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Biểu đồ tranh dùng hình để biểu diễn số liệu.","Phải đọc chú thích để biết mỗi hình tương ứng bao nhiêu."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c13-l4', 'g2-c13', 'Bài 4: Đọc biểu đồ tranh', 'learn', 'Đọc và so sánh số liệu trên biểu đồ tranh', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Trên biểu đồ, mỗi hình là 2 bạn đấy! Bé đếm cẩn thận nhé 🔍"}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Đếm hình rồi nhân","explanation":"Đếm số hình của từng nhóm, rồi NHÂN với số lượng mà mỗi hình biểu diễn.","rule":"Mỗi hình là 2 bạn. Nhóm thích táo có 3 hình, vậy có 3 × 2 = 6 bạn.","points":["Mỗi hình là 2 thì phải nhân với 2, không đếm hình không.","Muốn biết nhóm nào nhiều hơn, so số hình với nhau.","Tổng số bạn bằng tổng số hình nhân với số lượng mỗi hình."]}},{"type":"visual","content":{"text":"Mỗi hình = 2 bạn\nTáo: 3 hình → 3 × 2 = 6 bạn\nCam: 2 hình → 2 × 2 = 4 bạn","barChart":{"title":"Mỗi hình là 2 bạn","items":[{"label":"Táo","value":6},{"label":"Cam","value":4}],"unit":"bạn","highlight":0}}},{"type":"quiz","content":{"question":"Trên biểu đồ, mỗi hình là 2 bạn. Nhóm thích táo có 3 hình. Hỏi có bao nhiêu bạn thích táo?","options":[3,5,6,32],"answer":6,"items":[{"emoji":"🍎","count":3}],"mascotHint":"3 × 2 = 6 bạn."}},{"type":"quiz","content":{"question":"Táo có 3 hình, cam có 2 hình (mỗi hình là 2 bạn). Nhóm nào nhiều hơn và nhiều hơn bao nhiêu bạn?","options":["Táo, nhiều hơn 2 bạn","Cam, nhiều hơn 2 bạn","Bằng nhau","Táo, nhiều hơn 1 bạn"],"answer":"Táo, nhiều hơn 2 bạn","items":[{"emoji":"🍎","count":3},{"emoji":"🍊","count":2}],"mascotHint":"Táo 6 bạn, cam 4 bạn. 6 − 4 = 2 bạn."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Đếm số hình rồi nhân với số lượng mỗi hình.","3 × 2 = 6 bạn."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c13-l5', 'g2-c13', 'Bài 5: Chắc chắn, có thể, không thể', 'learn', 'Nhận biết khả năng xảy ra của một sự kiện', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Ngày mai trời mưa — điều đó có chắc chắn xảy ra không nhỉ? 🌦️"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Ba mức khả năng","explanation":"Một sự việc có thể CHẮC CHẮN xảy ra, CÓ THỂ xảy ra, hoặc KHÔNG THỂ xảy ra.","rule":"Mặt trời mọc ở hướng Đông: chắc chắn. Ngày mai trời mưa: có thể. Bé cao 3 mét: không thể.","points":["Chắc chắn: luôn luôn đúng.","Có thể: xảy ra hoặc không, không biết trước.","Không thể: chắc chắn không xảy ra."]}},{"type":"visual","content":{"text":"Chắc chắn: mặt trời mọc hướng Đông\nCó thể: ngày mai trời mưa\nKhông thể: bé cao 3 mét","table":{"headers":["Điều","Khả năng"],"rows":[["Mặt trời mọc ở hướng Đông","chắc chắn"],["Ngày mai trời mưa","có thể"],["Bé cao 3 mét","không thể"]],"label":"Chắc chắn · có thể · không thể"}}},{"type":"quiz","content":{"question":"Gieo một con xúc xắc, được mặt 7 chấm. Điều này thuộc mức nào?","options":["Chắc chắn","Có thể","Không thể","Vừa chắc chắn vừa có thể"],"answer":"Không thể","mascotHint":"Xúc xắc chỉ có 6 mặt, không bao giờ có mặt 7 chấm."}},{"type":"quiz","content":{"question":"Trong hộp chỉ có bi đỏ, lấy ra một viên bi đỏ. Điều này thuộc mức nào?","options":["Chắc chắn","Có thể","Không thể","Không xác định được"],"answer":"Chắc chắn","mascotHint":"Trong hộp chỉ có bi đỏ nên chắc chắn lấy được bi đỏ."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Ba mức: chắc chắn, có thể, không thể.","Trong hộp chỉ có bi đỏ thì lấy ra bi đỏ là chắc chắn."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c13-l6', 'g2-c13', 'Bài 6: Luyện tập chung chủ đề 13', 'learn', 'Ôn tập thống kê và khả năng xảy ra', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bé đã biết thu thập số liệu và đoán khả năng rồi! Tổng kết nhé 🎉"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Tổng kết chủ đề 13","explanation":"Bé đã học thu thập và phân loại số liệu, kiểm đếm, biểu đồ tranh và ba mức khả năng.","points":["Thu thập → phân loại → kiểm đếm → vẽ biểu đồ.","Biểu đồ tranh: mỗi hình tương ứng một số lượng.","Khả năng: chắc chắn, có thể, không thể."]}},{"type":"visual","content":{"text":"Thu thập → Phân loại → Kiểm đếm → Biểu đồ tranh","table":{"headers":["Bước","Việc làm"],"rows":[["1","Thu thập số liệu"],["2","Phân loại"],["3","Kiểm đếm"],["4","Vẽ biểu đồ tranh"]],"label":"Luyện tập chung chủ đề 13"}}},{"type":"quiz","content":{"question":"Trên biểu đồ, mỗi hình là 5 quả bóng. Nhóm có 4 hình. Hỏi nhóm đó có bao nhiêu quả bóng?","options":[9,20,45,54],"answer":20,"items":[{"emoji":"⚽","count":4}],"mascotHint":"4 × 5 = 20 quả bóng."}},{"type":"quiz","content":{"question":"Bé gieo một đồng xu, mặt sấp ngửa. Điều này thuộc mức nào?","options":["Chắc chắn","Có thể","Không thể","Không xác định"],"answer":"Có thể","mascotHint":"Đồng xu có thể ra mặt sấp hoặc mặt ngửa — đều có thể xảy ra."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Đếm hình rồi nhân với số lượng mỗi hình.","Bé đã hoàn thành chủ đề 13."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c14-l1', 'g2-c14', 'Bài 1: Ôn tập các số trong phạm vi 1 000', 'learn', 'Ôn tập đọc, viết, so sánh số trong phạm vi 1 000', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Sắp hết năm học rồi! Mình cùng ôn lại các số thật chắc nhé 📚"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Số trong phạm vi 1 000","explanation":"Bé nhớ lại cấu tạo số có ba chữ số và cách so sánh.","rule":"386 gồm 3 trăm, 8 chục, 6 đơn vị. 386 = 300 + 80 + 6. So sánh: 386 < 396 vì 8 chục < 9 chục.","points":["10 đơn vị = 1 chục; 10 chục = 1 trăm; 10 trăm = 1 nghìn.","Số tròn chục tận cùng là 0; số tròn trăm tận cùng là 00.","So hàng trăm → hàng chục → hàng đơn vị."]}},{"type":"visual","content":{"text":"386 = 300 + 80 + 6\n386  <  396","placeValue":{"headers":["Trăm","Chục","Đơn vị"],"digits":[3,8,6],"label":"386 = 300 + 80 + 6"},"comparison":{"left":386,"sign":"<","right":396}}},{"type":"quiz","content":{"question":"Số 386 gồm mấy trăm, mấy chục, mấy đơn vị?","options":["3 trăm, 8 chục, 6 đơn vị","6 trăm, 8 chục, 3 đơn vị","38 chục, 6 đơn vị","3 trăm, 6 chục, 8 đơn vị"],"answer":"3 trăm, 8 chục, 6 đơn vị","mascotHint":"Đọc từ trái sang: 3 là trăm, 8 là chục, 6 là đơn vị."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["386 = 300 + 80 + 6.","So sánh số: hàng trăm → hàng chục → hàng đơn vị."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c14-l2', 'g2-c14', 'Bài 2: Ôn tập phép cộng, phép trừ trong phạm vi 100', 'learn', 'Ôn tập phép cộng, phép trừ trong phạm vi 100 trước khi lên lớp 3', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Nhớ 1, mượn 1 — hai việc quan trọng nhất khi tính. Bé làm vài câu nhé! ✏️"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Cộng trừ trong phạm vi 100","explanation":"Cộng: nhớ 1 khi hàng đơn vị vượt 10. Trừ: mượn 1 chục khi không đủ để trừ.","rule":"46 + 38 = 84 (6+8=14 viết 4 nhớ 1; 4+3+1=8). 83 − 47 = 36 (13−7=6; 7−4=3).","points":["Luôn đặt tính thẳng cột.","Thử lại bằng phép tính ngược.","Bài toán ''thêm'' cộng, ''bớt'' trừ, ''hơn kém'' trừ."]}},{"type":"visual","content":{"text":"  46          83\n+ 38        − 47\n  84          36","operation":{"left":46,"sign":"+","right":38,"result":84},"table":{"headers":["Phép tính","Kết quả"],"rows":[["46 + 38","84"],["83 − 47","36"]],"label":"Ôn tập cộng trừ trong phạm vi 100"}}},{"type":"quiz","content":{"question":"57 + 26 bằng bao nhiêu?","options":[73,83,82,831],"answer":83,"mascotHint":"7+6=13 viết 3 nhớ 1; 5+2+1=8. Kết quả 83."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Cộng có nhớ: nhớ 1. Trừ có mượn: mượn 1 chục.","57 + 26 = 83."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c14-l3', 'g2-c14', 'Bài 3: Ôn tập phép cộng, phép trừ trong phạm vi 1 000', 'learn', 'Ôn tập cộng trừ với số có ba chữ số', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Ba chữ số cũng làm y như hai chữ số thôi. Bé thử nhé! 🔢"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Cộng trừ trong phạm vi 1 000","explanation":"Vẫn tính từ phải sang trái, vẫn nhớ và mượn như đã học.","rule":"235 + 412 = 647 (không nhớ). 256 + 173 = 429 (có nhớ). 534 − 268 = 266 (có mượn).","points":["Cộng không nhớ: từng hàng đều bé hơn 10.","Trừ không mượn: từng hàng đều trừ được.","Thử lại để chắc chắn."]}},{"type":"visual","content":{"text":"  256          534\n+ 173        − 268\n  429          266","operation":{"left":256,"sign":"+","right":173,"result":429},"table":{"headers":["Phép tính","Kết quả"],"rows":[["235 + 412","647 (không nhớ)"],["256 + 173","429 (có nhớ)"],["534 − 268","266 (có mượn)"]],"label":"Ôn tập cộng trừ trong phạm vi 1 000"}}},{"type":"quiz","content":{"question":"425 + 138 bằng bao nhiêu?","options":[553,563,573,462],"answer":563,"mascotHint":"5+8=13 viết 3 nhớ 1; 2+3+1=6; 4+1=5. Kết quả 563."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Cộng trừ số có ba chữ số làm như số có hai chữ số.","425 + 138 = 563."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c14-l4', 'g2-c14', 'Bài 4: Ôn tập phép nhân, phép chia', 'learn', 'Ôn tập bảng nhân 2, bảng nhân 5, bảng chia 2, bảng chia 5', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Bốn bảng nhân chia của bé vẫn còn nhớ chứ? Kiểm tra nhé! 🎯"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Bốn bảng của Lớp 2","explanation":"Lớp 2 học bốn bảng: nhân 2, nhân 5, chia 2, chia 5.","rule":"2 × 8 = 16; 5 × 7 = 35; 18 : 2 = 9; 45 : 5 = 9.","points":["Từ một phép nhân viết được hai phép chia.","5 × 7 = 35 → 35 : 5 = 7 và 35 : 7 = 5.","Đổi chỗ hai thừa số thì tích không đổi: 2 × 5 = 5 × 2."]}},{"type":"visual","content":{"text":"2 × 8 = 16\n5 × 7 = 35\n18 : 2 = 9\n45 : 5 = 9","operation":{"left":5,"sign":"×","right":7,"result":35},"table":{"headers":["Phép tính","Kết quả"],"rows":[["2 × 8","16"],["5 × 7","35"],["18 : 2","9"],["45 : 5","9"]],"label":"Ôn tập phép nhân, phép chia"}}},{"type":"quiz","content":{"question":"5 × 7 bằng bao nhiêu?","options":[12,30,35,40],"answer":35,"mascotHint":"5 × 7 = 35 (đếm thêm 5 bảy lần)."}},{"type":"quiz","content":{"question":"Có 18 cái kẹo chia đều cho 2 bạn. Mỗi bạn được mấy cái?","options":[6,8,9,16],"answer":9,"mascotHint":"18 : 2 = 9 cái kẹo."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Lớp 2 học bảng nhân 2, nhân 5, chia 2, chia 5.","5 × 7 = 35; 18 : 2 = 9."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c14-l5', 'g2-c14', 'Bài 5: Ôn tập hình học', 'learn', 'Ôn tập hình phẳng và hình khối đã học', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Hình phẳng và hình khối — bé còn nhớ hết không? 📐"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Tổng kết hình học Lớp 2","explanation":"Bé đã học điểm, đoạn thẳng, đường thẳng, đường cong, ba điểm thẳng hàng, đường gấp khúc, tứ giác, khối trụ và khối cầu.","rule":"Độ dài đường gấp khúc bằng tổng các đoạn. Hình tứ giác có 4 cạnh, 4 đỉnh.","points":["Khối trụ xếp chồng được; khối cầu lăn mọi hướng.","Đoạn thẳng có hai đầu mút; đường thẳng kéo dài mãi.","Muốn tính độ dài đường gấp khúc thì cộng các đoạn lại."]}},{"type":"visual","content":{"text":"Đường gấp khúc: cộng các đoạn\nKhối trụ xếp chồng · Khối cầu lăn","planeShape":{"kind":"rectangle","formula":"Hình tứ giác: 4 cạnh · 4 đỉnh"},"solid":{"kind":"sphere","dims":{"a":3},"label":"Khối cầu lăn mọi hướng"}}},{"type":"quiz","content":{"question":"Đường gấp khúc gồm 3 đoạn dài 5 cm, 6 cm và 7 cm. Độ dài đường gấp khúc là bao nhiêu?","options":["11 cm","18 cm","13 cm","567 cm"],"answer":"18 cm","mascotHint":"5 + 6 + 7 = 18 cm."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Đường gấp khúc: cộng độ dài các đoạn.","Khối trụ xếp chồng được, khối cầu thì không."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c14-l6', 'g2-c14', 'Bài 6: Ôn tập đo lường', 'learn', 'Ôn tập đơn vị đo độ dài, khối lượng, dung tích', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Bé đã học bao nhiêu đơn vị đo rồi nhỉ? Kể lại xem! 📏"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Các đơn vị đo của Lớp 2","explanation":"Độ dài: cm, dm, m, km. Khối lượng: kg. Dung tích: l. Thời gian: giờ, phút, ngày, tuần, tháng.","rule":"1 dm = 10 cm; 1 m = 100 cm; 1 km = 1000 m; 1 giờ = 60 phút; 1 tuần = 7 ngày.","points":["Chọn đơn vị đo phù hợp với vật.","1 ngày = 24 giờ; 1 năm = 12 tháng.","Số đo phải ghi kèm đơn vị."]}},{"type":"visual","content":{"text":"1 dm = 10 cm\n1 m = 100 cm\n1 km = 1000 m\n1 giờ = 60 phút","table":{"headers":["Đổi","Được"],"rows":[["1 dm","10 cm"],["1 m","100 cm"],["1 km","1000 m"],["1 giờ","60 phút"],["1 tuần","7 ngày"]],"label":"Ôn tập đo lường"}}},{"type":"quiz","content":{"question":"4 m bằng bao nhiêu xăng-ti-mét?","options":["40 cm","400 cm","4000 cm","14 cm"],"answer":"400 cm","mascotHint":"4 m = 4 × 100 = 400 cm."}},{"type":"quiz","content":{"question":"2 giờ bằng bao nhiêu phút?","options":["20 phút","60 phút","120 phút","100 phút"],"answer":"120 phút","mascotHint":"2 × 60 = 120 phút."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["1 m = 100 cm; 1 km = 1000 m.","1 giờ = 60 phút."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c14-l7', 'g2-c14', 'Bài 7: Ôn tập kiểm đếm số liệu và khả năng', 'learn', 'Ôn tập biểu đồ tranh và ba mức khả năng', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Biểu đồ tranh và ba mức khả năng — bài cuối cùng của phần thống kê! 📊"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Số liệu và khả năng","explanation":"Đọc biểu đồ tranh: đếm số hình rồi nhân với số lượng mỗi hình. Ba mức khả năng: chắc chắn, có thể, không thể.","rule":"Mỗi hình là 4 quyển vở, có 3 hình thì có 3 × 4 = 12 quyển vở.","points":["Đọc kĩ chú thích của biểu đồ trước khi tính.","So sánh hai nhóm thì so số hình với nhau.","Không thể: chắc chắn không xảy ra."]}},{"type":"visual","content":{"text":"Mỗi hình = 4 quyển\n3 hình → 3 × 4 = 12 quyển","barChart":{"title":"Số quyển vở đã quyên góp (mỗi hình = 4 quyển)","items":[{"label":"Nhóm 1","value":12},{"label":"Nhóm 2","value":8}],"unit":"quyển","highlight":0}}},{"type":"quiz","content":{"question":"Trên biểu đồ, mỗi hình là 4 quyển vở. Nhóm có 3 hình. Hỏi nhóm đó có bao nhiêu quyển vở?","options":[7,12,34,43],"answer":12,"items":[{"emoji":"📘","count":3}],"mascotHint":"3 × 4 = 12 quyển vở."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Đếm hình rồi nhân với số lượng mỗi hình.","Ba mức khả năng: chắc chắn, có thể, không thể."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c14-l8', 'g2-c14', 'Bài 8: Ôn tập chung cuối năm', 'learn', 'Ôn tập tổng hợp toàn bộ chương trình Lớp 2', 7, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Bé đã đi hết cả năm Lớp 2 rồi! Cùng nhìn lại chặng đường nhé 🎉"}},{"type":"concept","content":{"badge":"Ôn Tập Chung","title":"Cả năm Lớp 2 bé đã học gì?","explanation":"Số đến 1 000; cộng trừ có nhớ trong phạm vi 100 và 1 000; phép nhân chia với bảng 2 và bảng 5; đo lường; hình học và thống kê.","points":["Bốn phép tính: cộng, trừ, nhân, chia.","Đơn vị đo: cm, dm, m, km, kg, l, giờ, phút, tháng.","Hình: đường gấp khúc, tứ giác, khối trụ, khối cầu.","Thống kê: biểu đồ tranh; khả năng: chắc chắn, có thể, không thể."]}},{"type":"visual","content":{"text":"Số đến 1000 · Bốn phép tính · Đo lường · Hình học · Thống kê","table":{"headers":["Mạch kiến thức","Ví dụ"],"rows":[["Số đến 1000","386 = 300 + 80 + 6"],["Bốn phép tính","5 × 7 = 35"],["Đo lường","1 m = 100 cm"],["Hình học","khối trụ, khối cầu"],["Thống kê","biểu đồ tranh"]],"label":"Ôn tập chung cuối năm"}}},{"type":"quiz","content":{"question":"Một cửa hàng có 250 quyển vở, bán đi 135 quyển. Hỏi còn lại bao nhiêu quyển vở?","options":[115,125,135,385],"answer":115,"mascotHint":"250 − 135 = 115 quyển vở."}},{"type":"quiz","content":{"question":"Có 5 đĩa, mỗi đĩa 2 quả cam. Hỏi có tất cả bao nhiêu quả cam?","options":[7,10,12,25],"answer":10,"mascotHint":"2 × 5 = 10 quả cam."}},{"type":"summary","content":{"title":"Bé giỏi lắm:","points":["Bé đã ôn xong toàn bộ chương trình Lớp 2.","Bốn phép tính, đo lường, hình học và thống kê đều đã nắm chắc."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g2-c14-l9', 'g2-c14', 'Bài 9: Luyện đề cuối năm Lớp 2', 'learn', 'Luyện tập tổng hợp dạng đề kiểm tra cuối năm', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Đây là những dạng bài bé sẽ gặp trong bài kiểm tra cuối năm. Mình thử sức nhé! 🏆"}},{"type":"concept","content":{"badge":"Luyện Đề","title":"Các dạng bài thường gặp","explanation":"Đề cuối năm thường có: đọc viết số, so sánh số, đặt tính rồi tính, tìm thành phần chưa biết, bài toán có lời văn, hình học và thống kê.","points":["Đặt tính cẩn thận, đừng quên nhớ và mượn.","Đọc kĩ đề để chọn đúng phép tính.","Ghi đơn vị và đáp số đầy đủ."]}},{"type":"visual","content":{"text":"Đọc số · So sánh · Đặt tính · Tìm x · Giải toán · Hình học · Biểu đồ","table":{"headers":["Dạng bài","Ví dụ"],"rows":[["Đọc số","386"],["So sánh","386 < 396"],["Đặt tính","256 + 173 = 429"],["Tìm x","x + 145 = 320"],["Giải toán","245 + 168 = 413"],["Hình học","khối cầu"],["Biểu đồ","mỗi hình = 4 quyển"]],"label":"Luyện đề cuối năm Lớp 2"}}},{"type":"quiz","content":{"question":"Tìm số còn thiếu: 700 − ? = 350","options":[250,350,450,1050],"answer":350,"mascotHint":"Số trừ = 700 − 350 = 350."}},{"type":"quiz","content":{"question":"Một hình vuông có cạnh dài 4 cm. Chu vi hình vuông là bao nhiêu?","options":["8 cm","12 cm","16 cm","44 cm"],"answer":"16 cm","mascotHint":"Chu vi hình vuông = 4 × 4 = 16 cm."}},{"type":"summary","content":{"title":"Bé giỏi lắm:","points":["Bé đã hoàn thành chương trình Toán Lớp 2 theo đúng SGK.","Chúc mừng bé lên Lớp 3!"],"mascotMood":"celebrate"}}]}'::jsonb, NOW())
