-- SINH TỰ ĐỘNG bởi scripts/migrate-content.mjs — ĐỪNG SỬA TAY.
-- Chạy trong Supabase SQL Editor, theo thứ tự tên file.
-- Chạy lại được nhiều lần (ON CONFLICT … DO UPDATE) nên không sinh dòng trùng.

-- Bài học Lớp 2 — 120 bài

ON CONFLICT (id) DO UPDATE SET
  chapter_id = EXCLUDED.chapter_id, title = EXCLUDED.title,
  lesson_type = EXCLUDED.lesson_type, description = EXCLUDED.description,
  sort_order = EXCLUDED.sort_order, status = EXCLUDED.status,
  payload = EXCLUDED.payload, published_at = NOW(), updated_at = NOW();

-- Phiên bản 1 cho các bài của Lớp 2
SELECT id, 1, title, description, lesson_type, payload
FROM public.content_lessons
WHERE chapter_id LIKE 'g2-%'
ON CONFLICT (lesson_id, version) DO NOTHING;
